/**
 * Docs sidebar — the order is the reading order:
 *
 *   Getting started → Sources & coverage → How it's built → Guides → Tutorials →
 *   Reference (ESPN leagues by sport + providers) → Utilities → API reference →
 *   Changelog.
 *
 * Guides, Tutorials and the TypeDoc API tree stay AUTOGENERATED from their folders
 * (`dirName`), so a new page there surfaces with no edit here — each wrapped in an
 * explicit category, because a root-level `autogenerated` splices the folder's pages
 * flat and ignores its `_category_.json` (that is how tutorials once interleaved with
 * guides). The Reference,
 * "How this library is built" and Utilities groups are built by codegen into
 * `docs/src/generated/reference-sidebar.js` (from `tools/codegen/endpoints/leagues.yaml`,
 * `architecture.mjs` and `utilities.yaml`), so a new league / provider / utility
 * module lands in the right group — no manual sidebar edit.
 */
const generated = require('./src/generated/reference-sidebar.js');

module.exports = {
  docs: [
    { type: 'doc', id: 'intro', label: 'Getting started' },
    { type: 'doc', id: 'sources', label: 'Sources & coverage' },
    // How this library is built (generated status blocks; prose hand-authored).
    generated.architecture,
    {
      type: 'category',
      label: 'Guides',
      collapsible: true,
      collapsed: false,
      link: {
        type: 'generated-index',
        slug: '/guides',
        title: 'Guides & recipes',
        description:
          'Per-area, copy-pasteable recipes — raw vs parsed, one runnable snippet at a time, each with an "Open in playground" link.',
      },
      items: [{ type: 'autogenerated', dirName: 'guides' }],
    },
    {
      type: 'category',
      label: 'Tutorials',
      collapsible: true,
      collapsed: false,
      link: { type: 'doc', id: 'tutorials/index' },
      items: [{ type: 'autogenerated', dirName: 'tutorials' }],
    },
    { type: 'link', label: 'Playground', href: '/playground' },
    {
      type: 'category',
      label: 'Reference',
      collapsible: true,
      collapsed: true,
      // Generated, grouped-by-sport reference tree (drift-guarded by codegen).
      items: generated.reference,
    },
    // Hand-written non-data exports, by category (tools/codegen/utilities.yaml).
    generated.utilities,
    {
      type: 'category',
      label: 'API reference (TypeDoc)',
      collapsible: true,
      collapsed: true,
      link: { type: 'doc', id: 'api/index' },
      items: [{ type: 'autogenerated', dirName: 'api' }],
    },
    { type: 'link', label: 'Changelog', href: '/CHANGELOG' },
  ],
};
